#[path = "solution.rs"]
mod solution;

use solution::{build_atlas, AtlasError, Tile};

fn tile(width: usize, height: usize, pixels: &[u8]) -> Tile {
    Tile { width, height, pixels: pixels.to_vec() }
}

#[test]
fn places_tiles_row_major_and_zero_fills_unused_cells() {
    let tiles = vec![
        tile(2, 1, &[1, 2]),
        tile(2, 1, &[3, 4]),
        tile(2, 1, &[5, 6]),
    ];
    let atlas = build_atlas(&tiles, 2).unwrap();

    assert_eq!(atlas.width, 4);
    assert_eq!(atlas.height, 2);
    assert_eq!(atlas.pixels, vec![1, 2, 3, 4, 5, 6, 0, 0]);
    assert_eq!(tiles[0].pixels, vec![1, 2]);
    assert_eq!(tiles[1].pixels, vec![3, 4]);
    assert_eq!(tiles[2].pixels, vec![5, 6]);
}

#[test]
fn reports_dedicated_argument_errors_in_required_order() {
    assert!(matches!(build_atlas(&[], 3), Err(AtlasError::EmptyInput)));

    let invalid = vec![tile(2, 2, &[])];
    assert!(matches!(build_atlas(&invalid, 0), Err(AtlasError::ZeroColumns)));
}

#[test]
fn reports_lowest_invalid_buffer_and_dimension_indices() {
    let bad_pixels = vec![
        tile(1, 1, &[7]),
        tile(1, 1, &[]),
        tile(1, 1, &[]),
    ];
    assert!(matches!(
        build_atlas(&bad_pixels, 1),
        Err(AtlasError::InvalidPixels { index: 1 })
    ));

    let bad_dimensions = vec![
        tile(1, 1, &[7]),
        tile(1, 1, &[8]),
        tile(2, 1, &[9, 10]),
    ];
    assert!(matches!(
        build_atlas(&bad_dimensions, 2),
        Err(AtlasError::DimensionMismatch { index: 2 })
    ));
}

#[test]
fn accepts_empty_tile_dimensions_with_empty_buffers() {
    let tiles = vec![tile(0, 0, &[]), tile(0, 0, &[])];
    let atlas = build_atlas(&tiles, 3).unwrap();
    assert_eq!(atlas.width, 0);
    assert_eq!(atlas.height, 0);
    assert!(atlas.pixels.is_empty());
}

#[test]
fn arithmetic_overflow_is_an_error_not_a_panic() {
    let tiles = vec![Tile { width: usize::MAX, height: 2, pixels: Vec::new() }];
    assert!(matches!(build_atlas(&tiles, 1), Err(AtlasError::Overflow)));

    let zero_area = vec![Tile { width: usize::MAX, height: 0, pixels: Vec::new() }];
    assert!(matches!(build_atlas(&zero_area, 2), Err(AtlasError::Overflow)));
}

